import itertools,json
jobs='ABCDE'
slot={'A':[0,1,4,11,3],'B':[2,3,3,2,5],'C':[4,8,2,10,8],'D':[3,2,11,3,4],'E':[10,6,10,10,4]}
transfer=dict(zip(jobs,[[0,3,3,0,5],[5,0,4,2,0],[2,2,0,2,5],[0,5,5,0,5],[1,4,3,1,0]]))
def nominal(r):
 return sum(slot[j][i] for i,j in enumerate(r))+sum(transfer[a][jobs.index(b)] for a,b in zip(r,r[1:]))
def legal(r,s):
 if r.index('A')>r.index('D'): return False
 return {'rain':r[0] not in 'DA','road':r[3]!='C' and r[1]!='E','lift':r[0] not in 'AB'}[s]
def penalty(r,s):
 j,threshold,rate={'rain':('C',1,6),'road':('D',3,6),'lift':('E',2,10)}[s]
 return max(0,r.index(j)+1-threshold)*rate
results=[]
for p in itertools.permutations(jobs):
 if p.index('A')>p.index('D'): continue
 neighbors=[(p,0)]
 for i,j in itertools.combinations(range(5),2):
  r=list(p);r[i],r[j]=r[j],r[i]
  neighbors.append((tuple(r),1))
 best={}
 for s in ['rain','road','lift']:
  options=[(nominal(r)+penalty(r,s)+fee,''.join(r)) for r,fee in neighbors if legal(r,s)]
  if not options: break
  best[s]=min(options)
 if len(best)==3: results.append((nominal(p)+max(v[0] for v in best.values()),''.join(p),best))
results.sort()
score,p,best=results[0]
answer={'roster':p,'score':score,'repairs':{s:v[1] for s,v in best.items()},'repair_costs':{s:v[0] for s,v in best.items()},'feasible_count':len(results),'next_score':min(v[0] for v in results if v[0]>score)}
payload=json.dumps(answer)
# Independent verification: compare every final permutation by Hamming distance,
# compute costs via explicit adjacent matrix and position dictionaries.
rows=[slot[j] for j in jobs]; matrix=[transfer[j] for j in jobs]
def check_cost(q,s=None,p=None):
 indices=[ord(x)-65 for x in q]
 total=sum(rows[indices[k]][k] for k in range(5))
 for k in range(4): total+=matrix[indices[k]][indices[k+1]]
 if s:
  pos={j:q.index(j)+1 for j in jobs}
  if s=='rain': total+=6*(pos['C']-1)
  if s=='road': total+=6*max(pos['D']-3,0)
  if s=='lift': total+=10*max(pos['E']-2,0)
  total+=int(q!=p)
 return total
allr=[''.join(x) for x in itertools.permutations(jobs) if x.index('A')<x.index('D')]
verified=[]
for pub in allr:
 costs=[]
 for s in ['rain','road','lift']:
  vals=[]
  for q in allr:
   if sum(a!=b for a,b in zip(pub,q)) not in (0,2): continue
   if s=='rain' and (q[0]=='D' or q[0]=='A'): continue
   if s=='road' and (q[3]=='C' or q[1]=='E'): continue
   if s=='lift' and (q[0]=='A' or q[0]=='B'): continue
   vals.append(check_cost(q,s,pub))
  if not vals: break
  costs.append(min(vals))
 if len(costs)==3: verified.append((check_cost(pub)+max(costs),pub,costs))
a=json.loads(payload)
assert len(verified)==a['feasible_count']
assert min(x[0] for x in verified)==a['score']
assert min(x[0] for x in verified if x[0]>a['score'])==a['next_score']
chosen=next(x for x in verified if x[1]==a['roster'])
for s,c in zip(['rain','road','lift'],chosen[2]):
 q=a['repairs'][s]
 assert q in allr and sum(x!=y for x,y in zip(q,a['roster'])) in (0,2)
 assert legal(q,s) and check_cost(q,s,a['roster'])==c==a['repair_costs'][s]
assert a['score']==check_cost(a['roster'])+max(a['repair_costs'].values())
print(payload)
print('Verified independently over all publication/final permutation pairs.')

